package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class RecordatorioService { private final RecordatorioCitaRepository repo; private final CitaRepository citas; public RecordatorioService(RecordatorioCitaRepository r,CitaRepository c){repo=r;citas=c;} public List<RecordatorioCita> listar(UUID e){return repo.findByEmpresaIdOrderByFechaProgramadaDesc(e);} public RecordatorioCita crear(UUID e,UUID citaId,String canal,LocalDateTime fecha){Cita c=citas.findById(citaId).filter(x->e.equals(x.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("Cita no encontrada para esta empresa."));if(!List.of("CORREO","INTERNA").contains(canal))throw new IllegalArgumentException("Canal no disponible."); RecordatorioCita r=new RecordatorioCita();r.setEmpresaId(e);r.setCita(c);r.setCanal(canal);r.setFechaProgramada(fecha);return repo.save(r);} }
